# 模拟 Hive JOIN 策略选择: 小表广播(MapJoin) vs 常规 Shuffle(CommonJoin)
MAPJOIN_THRESHOLD_MB = 25.0   # hive.auto.convert.join 默认约 25MB

def choose_join(big_mb, small_mb):
    if small_mb <= MAPJOIN_THRESHOLD_MB:
        return "MapJoin(广播小表)", (
            f"小表 {small_mb}MB <= {MAPJOIN_THRESHOLD_MB}MB 阈值, 把小表放进分布式缓存广播到各 Map 任务, "
            "大表在 Map 端直接关联, 本次 JOIN 完全消除 Shuffle, 无 Reducer 阶段")
    return "CommonJoin(Shuffle Join)", (
        f"两表均 > {MAPJOIN_THRESHOLD_MB}MB, 必须按 join key 做哈希分区, 跨网络 Shuffle 后 Reducer 端做关联")

cases = [
    ("大表 2GB JOIN 维度小表 8MB", 2048, 8),
    ("大表 2GB JOIN 较大表 200MB", 2048, 200),
]
for name, big, small in cases:
    strat, reason = choose_join(big, small)
    print(f"场景: {name}")
    print(f"  选择: {strat}")
    print(f"  原因: {reason}\n")
print("提示: hive.auto.convert.join=true 时优化器自动选 MapJoin; 也可写 /*+ MAPJOIN(dim) */ 强制。")
